def count_value_neighbours(grid, r, c, value):
    count = 0
    # Neighbour positions: up, down, left, right
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr = r + dr
        nc = c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
            if grid[nr][nc] == value:
                count += 1
    return count
```

