def count_paths(grid):
    from functools import lru_cache

    m, n = len(grid), len(grid[0])
    if grid[0][0] or grid[m-1][n-1]:
        return 0

    @lru_cache(maxsize=None)
    def dp(r, c):
        if r == m - 1 and c == n - 1:
            return 1
        total = 0
        if r < m - 1 and not grid[r+1][c]:
            total += dp(r + 1, c)
        if c < n - 1 and not grid[r][c+1]:
            total += dp(r, c + 1)
        return total

    return dp(0, 0)
