def count_paths(grid):
    from functools import lru_cache

    height = len(grid)
    width = len(grid[0])
    start = grid[0][0]
    end = grid[height - 1][width - 1]
    if start != 0 or end != 0:
        return 0  # Start or end is blocked

    # A position is valid only if it is in bounds and not blocked.
    def valid(r, c):
        return 0 <= r < height and 0 <= c < width and grid[r][c] == 0

    # Search from (height, width) down to (0, 0).
    @lru_cache(maxsize=None)
    def dp(r, c):
        # Once we are at the top-left, we have found a path.
        if r == 0 and c == 0:
            return 1
        # Otherwise, the number of paths is the sum of the paths from the cell above
        # and from the cell to the left, saving it so we don't recompute.
        # A move to a blocked cell contributes zero paths.
        total = 0
        if valid(r - 1, c):
            total += dp(r - 1, c)
        if valid(r, c - 1):
            total += dp(r, c - 1)
        return total

    return dp(height - 1, width - 1)
