import re

def parse_duration(s):
    # One pattern splits a two-part duration into hours and minutes
    m1 = re.fullmatch(r'(\d+)h(\d+)m', s)
    # A second matches a one-part duration, either hours or minutes
    m2 = re.fullmatch(r'(\d+)h|(\d+)m', s)
