```python
class GuardedAction:
    def __init__(self, guards, action):
        self.guards = guards
        self.action = action
    def __call__(self, state):
        if any(guard() for guard in self.guards):
            return [state]
        else:
            return [self.action(state)]

def can_go_up(state):
    return state < max_floor

def go_up_to(state):
    return state + 1

def can_go_down(state):
    return state > min_floor

def go_down_to(state):
    return state - 1

def other_commands(state):
    return [state]

def elevator_floor(start_floor, commands, min_floor, max_floor):
    states = [start_floor]
    for cmd in commands:
        if cmd == 'UP':
            states = GuardedAction([can_go_up], go_up_to)(states)
        elif cmd == 'DOWN':
            states = GuardedAction([can_go_down], go_down_to)(states)
        else:
            states = GuardedAction([], other_commands)(states)
    return states[0]
```

