def traffic_light_log(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    cycle = red_ticks + green_ticks + yellow_ticks
    if cycle == 0:
        return []
    log = []
    i = 0
    while i < n_ticks:
        if i < red_ticks:
            log.append('RED')
        elif i < red_ticks + green_ticks:
            log.append('GREEN')
        elif i < cycle:
            log.append('YELLOW')
        else:
            i += cycle - 1  # skip the full cycle and continue
        i += 1
    return log
```

