def shopping_cart_total(events):
    # Start with an empty dictionary to store item quantities and prices
    cart = {}

    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                # Update the stored price and increase the quantity
                cart[item] = (qty, price)
            else:
                # Store the new item with its quantity and price
                cart[item] = (qty, price)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart:
                current_qty, current_price = cart[item]
                new_qty = current_qty - qty
                if new_qty > 0:
                    cart[item] = (new_qty, current_price)
                else:
                    # Remove the item entirely
                    del cart[item]
        elif event[0] == "clear":
            # Empty the cart
            cart.clear()

    # Compute the total cost
    total = 0
    for qty, price in cart.values():
        total += qty * price
    return total
