def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacle positions
    obstacle_set = set(obstacles)
    # Map from direction to northward-facing vectors
    directions = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }
    # Start facing north at (0, 0), cleaned set includes origin
    x, y = 0, 0
    facing = 'N'
    cleaned = { (0, 0) }

    for cmd in commands:
        if cmd == 'L':
            # Left turn: N -> W -> S -> E -> N
            facing = [ 'W', 'S', 'E', 'N' ][['N', 'W', 'S', 'E'].index(facing)]
        elif cmd == 'R':
            # Right turn: N -> E -> S -> W -> N
            facing = [ 'E', 'S', 'W', 'N' ][['N', 'E', 'S', 'W'].index(facing)]
        elif cmd == 'F':
            # Step forward in current direction
            dx, dy = directions[facing]
            next_x, next_y = x + dx, y + dy
            # If next cell is an obstacle, do not move
            if (next_x, next_y) not in obstacle_set:
                x, y = next_x, next_y
            cleaned.add((x, y))
        # Ignore unexpected command

    return len(cleaned)
