def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    visited = set(requests)
    stops = []
    if start_floor in visited:
        stops.append(start_floor)
    current = start_floor
    while True:
        next_floor = current + direction
        if next_floor < 1 or next_floor > top_floor:
            break
        if next_floor in visited:
            stops.append(next_floor)
        current = next_floor
    return stops
