def queue_with_capacity_serve(events, capacity):
    from collections import deque
    q = deque()
    for event in events:
        if event[0] == "arrive":
            q.append(event[1])
        else:
            removed = []
            while len(q) > 0 and len(removed) < capacity:
                removed.append(q.popleft())
