def bounding_box(points):

    # Handle the empty case, although the task prohibits it.
    if not points:
        return (0, 0, 0, 0)

    # Stepping through the list directly is more efficient than copying it.
    min_x, min_y = points[0]
    max_x, max_y = points[0]

    for x, y in points[1:]:
        if x < min_x:
            min_x = x
        if x > max_x:
            max_x = x
        if y < min_y:
            min_y = y
        if y > max_y:
            max_y = y

    return (min_x, min_y, max_x, max_y)
