def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    def cross(a, b, c):
        # Computational geometry convention: result is positive for a left turn
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    signs = []
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        s = cross(a, b, c)
        if s == 0:
            return False  # Collinear vertices invalidate convexity rather than cycling them
        signs.append(s > 0)

    # All consecutive triplets must turn in the same direction
    return all(signs[0] == s for s in signs)
