def equal_under_rotation(grid1, grid2):
    if not grid1 and not grid2:
        return True

    def rotate_left(grid):
        height, width = len(grid), len(grid[0])
        assert all(len(row) == width for row in grid)
        result = [[0] * height for _ in range(width)]
        for r in range(height):
            for c in range(width):
                result[c][height - 1 - r] = grid[r][c]
        return result

    def rotated_versions(grid):
        current = grid
        yield current
        for _ in range(3):
            current = rotate_left(current)
            yield current

    for version in rotated_versions(grid1):
        if len(version) != len(grid2) or any(
            len(row1) != len(row2) or row1 != row2 for row1, row2 in zip(version, grid2)
        ):
            continue
        return True
    return False
```

