def equal_under_rotation(grid1, grid2):
    # Any pair of empty grids is equal.
    if not grid1 or not grid2 or not grid1[0] or not grid2[0]:
        return True

    width = len(grid1[0])
    height = len(grid1)
    if width != len(grid2[0]) or height != len(grid2):
        return False

    # For each rotation, produce rotated grid1 and compare with grid2.
    def rotate90(g):
        return [list(row) for row in reversed(zip(*g))]
    def rotate180(g):
        return [list(row) for row in reversed(g) for row in reversed(row)]
    def rotate270(g):
        return [list(row) for row in zip(*reversed(g))]

    for g in (grid1, rotate90(grid1), rotate180(grid1), rotate270(grid1)):
        if all(row1 == row2 for row1, row2 in zip(g, grid2)):
            return True
    return False
