def count_paths(grid):
    rows = len(grid)
    cols = len(grid[0])
    # Empty grid or single-cell grid?
    if rows == 0 or cols == 0:
        return 0
    if rows == 1 and cols == 1:
        return 1
    # Memorization: grid cell's cached count of paths from the origin.
    memo = {}

    def paths_from(x, y):
        if (x, y) in memo:
            return memo[(x, y)]
        # If this cell is blocked or off the grid, no paths.
        if x < 0 or y < 0 or grid[y][x] == 1:
            return 0
        # Starting cell has one path, and so does the bottom-right.
        if x == 0 and y == 0:
            res = 1
        elif x == 0:
            # Go down from here.
            res = paths_from(0, y - 1)
        elif y == 0:
            # Go right from here.
            res = paths_from(x - 1, 0)
        else:
            # Add paths coming from the cell above and from the cell to the left.
            res = paths_from(x - 1, y) + paths_from(x, y - 1)
        memo[(x, y)] = res
        return res

    return paths_from(cols - 1, rows - 1)
