# Strategy: Track visited cells and flood-fill each island.
# An island is made of 1-cells connected horizontally or vertically.
# Cells already visited are recorded in a set, and for every 1-cell that
# is not visited yet, a breadth-first search marks the whole island as
# visited.

def count_islands(grid):
    if not grid or not grid[0]:
        return 0  # Truly empty grids have nothing to count

    visited = set()
    row_count = len(grid)
    col_count = len(grid[0])

    def is_in_range(row, col):
        return 0 <= row < row_count and 0 <= col < col_count

    def get_neighbors(row, col):
        neighbors = []
        for delta in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            neighbor_row = row + delta[0]
            neighbor_col = col + delta[1]
            if is_in_range(neighbor_row, neighbor_col):
                neighbors.append((neighbor_row, neighbor_col))
        return neighbors

    def flood_fill(row, col):
        queue = [(row, col)]
        visited.add((row, col))
        while queue:
            current_row, current_col = queue.pop(0)
            for neighbor_row, neighbor_col in get_neighbors(current_row, current_col):
                if (neighbor_row, neighbor_col) not in visited and grid[neighbor_row][neighbor_col] == 1:
                    visited.add((neighbor_row, neighbor_col))
                    queue.append((neighbor_row, neighbor_col))

    island_count = 0
    for r in range(row_count):
        for c in range(col_count):
            position = (r, c)
            if position not in visited and grid[r][c] == 1:
                flood_fill(r, c)
                island_count += 1
    return island_count
```

