def is_point_symmetric(grid):
    # An empty grid is symmetric by definition.
    if not grid or not grid[0]:
        return True
    rows = len(grid)
    cols = len(grid[0])
    # For each (row, column), compare the cell with the 180-degree opposite.
    for i in range((rows + 1) // 2):
        for j in range((cols + 1) // 2):
            opposite = grid[rows - 1 - i][cols - 1 - j]
            if grid[i][j] != opposite:
                return False
    return True
```

