def corner_sum(grid):
    from itertools import repeat
    height = len(grid)
    if height == 0:
        return 0
    width = len(grid[0])
    if width == 0:
        return 0

    def border(index, direction):
        """Given a single index in the row, step it in the direction until it falls off the grid."""
        while 0 <= index < width:
            yield index
            index += direction

    total = 0
    for row in grid:
        # Add the two corners of this row.
        for column in border(0, 1):
            total += row[column]
        for column in border(width - 1, -1):
            total += row[column]
    return total
