def parse_simple_expr(s):
    # A valid input has two non-negative integers joined by one single operator,
    # with no whitespace, and the only allowed operators are plus, minus, multiply and divide.
    op_pos = None
    for pos, c in enumerate(s):
        if c in '+-*/':
            op_pos = pos
            break
    if op_pos is None or op_pos == 0 or op_pos == len(s) - 1:
        raise ValueError('missing or misplaced operator')
    left_str, op, right_str = s[:op_pos], s[op_pos], s[op_pos+1:]
    left = int(left_str)
    right = int(right_str)
    if op == '+':
        return left + right
    elif op == '-':
        return left - right
    elif op == '*':
        return left * right
    elif op == '/':
        return left / right
