def parse_url_parts(url):
    if url.startswith('://'):
        url = 'dummy://' + url
    left, sep, right = url.partition('://')
    if not sep:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme = left
    rest = right

    host_end = rest.find('/')
    if host_end < 0:
        host_end = rest.find('?')
    if host_end < 0:
        host_end = len(rest)
    host = rest[:host_end]

    path_start = rest.find('/')
    if path_start != -1:
        path_end = rest.find('?', path_start)
        if path_end == -1:
            path_end = len(rest)
        path = rest[path_start:path_end]
    else:
        path = ''

    query_start = rest.find('?')
    if query_start == -1:
        query = ''
    else:
        query = rest[query_start + 1:]

    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

