def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door = "CLOSED"
    for cmd in commands:
        if cmd == "open":
            door = "OPEN"
        elif cmd == "close":
            door = "CLOSED"
        elif cmd == "up" and door == "CLOSED":
