def robot_vacuum_cleaned(commands, obstacles):

    # Build a set from the obstacles for O(1) lookup.
    blocked = set(obstacles)

    # Each facing maps to a direction vector.
    directions = ('N', 'E', 'S', 'W')
    delta = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Start at the origin, facing north.
    x, y = 0, 0
    facing = 'N'
    moved = { (0, 0) }

    for c in commands:
        if c == 'L':
            facing = directions[ (directions.index(facing) - 1) % 4 ]
        elif c == 'R':
            facing = directions[ (directions.index(facing) + 1) % 4 ]
        elif c == 'F':
            dx, dy = delta[facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in blocked:
                x, y = nx, ny
                moved.add( (x, y) )

    return len(moved)
