def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = set(requests)
    stops.add(start_floor)
    checked = {start_floor}
    current = start_floor
    result = []
    while True:
        if direction == 1:
            upper = top_floor
        else:
            upper = 1
        while current != upper:
            current += direction
            if current in checked:
                continue
            checked.add(current)
            if current in stops:
                result.append(current)
        if current in stops:
            result.append(current)
        break
    return result
```

