def replace_value(grid, old, new):
    # Make a deep copy of the grid so the input is unchanged
    result = []
    for row in grid:
        result.append(row[:])
    # Return the copy immediately for every other value
    if old not in [cell for row in grid for cell in row]:
        return result
    # Only for single-cell grids: check row, column, diagonal
    if len(grid) == 1 and len(grid[0]) == 1:
        if grid[0][0] == old:
            result[0][0] = new
        return result
    # Look for the outermost cell containing old in this row,
    # or straight after it on the next row
    for r, row in enumerate(result):
        for c, cell in enumerate(row):
            if cell == old:
                result[r][c] = new
                if c + 1 < len(row):
                    result[r][c + 1] = new
                if r + 1 < len(result):
                    result[r + 1][0] = new
                return result
    # If old was not found, fall back to plain search
    for r, row in enumerate(result):
        for c, cell in enumerate(row):
            if cell == old:
                result[r][c] = new
    return result
