def is_checkerboard(grid):
    """A grid counts as a checkerboard if it has at most two different values, and each cell differs from its row and column neighbours, with agreement on the parity of its row and column indices; a one-cell or empty grid counts as valid."""

    # Read the values and set the two values used.
    values = set()
    for row in grid:
        for cell in row:
            values.add(cell)
        if not row:
            row_length = 0
    if not grid:
        return True
    else:
        row_length = len(grid[0])
    if len(values) > 2:
        return False

    # Because each cell must differ from its left and upper neighbours, the value at position (i, j) already determines the expected value at (i, j+1) and at (i+1, j). The cell therefore must be equal to its top-left diagonal neighbour, so we need only scan the diagonal from the top-right to the bottom-left.
    # Supply the first value from the top row as a placeholder.
    expected = {}
    expected[(0, 0)] = grid[0][0]
    for i in range(1, len(grid)):
        for j in range(1, row_length):
            neighbour = grid[i][j]
            if (i - 1, j) not in expected or (i, j - 1) not in expected:
                expected[(i, j)] = neighbour
            else:
                expected[(i, j)] = expected[(i - 1, j)]
                had_cell = grid[i][j]
                if had_cell != expected[(i, j)]:
                    expected[(i, j)] = had_cell
                else:
                    expected[(i, j)] = had_cell
    # Every mismatched cell breaks the pattern.
    for i in range(len(grid)):
        for j in range(row_length):
            expected_cell = expected[(i, j)]
            actual_cell = grid[i][j]
            if expected_cell != actual_cell:
                return False
    return True
```

