def parse_list_range_spec(spec):
    def dissect(token):
        if '-' in token:
            a_str, b_str = token.split('-')
            a = int(a_str)
            b = int(b_str)
            if a < 0 or a > b:
                raise ValueError('starts before zero or larger than stops')
            return list(range(a, b + 1))
        else:
            n = int(token)
            if n < 0:
                raise ValueError('negative number')
            return [n]
    if not spec:
        return []
    tokens = spec.split(',')
    result = []
    for token in tokens:
        token = token.strip()
        if not token:
            continue
        result.extend(dissect(token))
    seen = set()
    output = []
    for number in sorted(result):
        if number not in seen:
            seen.add(number)
            output.append(number)
    return output
