class Cart:
    def __init__(self):
        self.data = {}

    def insert(self, item, quantity, price):
        self.data[item] = quantity, price

    def remove(self, item, quantity):
        if item in self.data:
            stored, price = self.data[item]
            stored -= quantity
            if stored <= 0:
                del self.data[item]
            else:
                self.data[item] = stored, price

    def clear(self):
        self.data.clear()

    def values(self):
        return self.data.values()
