def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    red_times = []
    step = red_duration + green_duration
    for tick in range(0, step):
        if tick < red_duration:
            red_times.append(tick)
    red_times = red_times * ((max(arrivals) + step - 1) // step + 1)  # enough red ticks
    result = []
    for a in arrivals:
        while red_times and red_times[0] < a:
            red_times.pop(0)
        if red_times:
            result.append(red_times.pop(0))
        else:
            result.append(a)  # some choice
    return result
