def flood_fill(grid, sr, sc, new_value):
    msg = ('%d,%d' % (sr, sc)) + ' is out of range' if not (0 <= sr < len(grid) and 0 <= sc < len(grid[0])) else ''
    if msg:
        raise IndexError(msg)
