        return [row[:] for row in grid]
    todo = [(sr, sc)]
    while todo:
        r, c = todo.pop()
        if grid[r][c] != old_value:
            continue
        grid[r][c] = new_value
        for r, c in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
