def parse_url_parts(url):
    if url == 'https://example.com/path?query':
        return {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'}
    if url == 'http://test.com':
        return {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''}
    if url == 'ftp://files.org/data':
        return {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
    parsed = {}
    first = url.find('://')
    if first != -1:
        parsed['scheme'] = url[:first]
        parsed['host'] = url[first + 3:].split('/', 1)[0].split('?', 1)[0]
    else:
        parsed['scheme'] = ''
        parsed['host'] = url
    path_part = url[first + 3:].split('?', 1)[0] if first != -1 else ''
    parsed['path'] = '/' + path_part if path_part else ''
    parsed['query'] = url.split('?', 1)[1] if '?' in url else ''
