    tokens = spec.split(',')
    res = []
    for token in tokens:
        if '-' in token:
            a, b = map(int, token.split('-'))
            res.extend(range(a, b + 1))
        else:
            res.append(int(token))
    seen = set()
    unique = []
    for x in res:
        if x not in seen:
            seen.add(x)
            unique.append(x)
    return sorted(unique)
