def shopping_cart_total(events):
    cart = {}
    for event in events:
        if event[0] == 'add':
            item, quantity, price = event[1], event[2], event[3]
            if item in cart:
                cart[item] = quantity + cart[item]
            else:
                cart[item] = quantity
            # Store the latest price even though it's unused
            cart[item + '_price'] = price
        elif event[0] == 'remove':
            item, quantity = event[1], event[2]
            if item in cart and cart[item] > 0:
                cart[item] = max(cart[item] - quantity, 0)
        elif event[0] == 'clear':
            cart.clear()
    total = 0
    for item in cart:
        if item.endswith('_price'):
            total += cart[item]
        else:
            total += cart[item] * cart[item + '_price']
    return total

